//! Regenerates `web/src/gen/constants.ts` from the Rust single-owners, so
//! the client never hand-syncs TICK_HZ / the Q16.16 scale / the rarity
//! ladder. CI runs this and `git diff --exit-code web/src/gen` — the same
//! freshness guard that covers the protocol bindings.
//!
//! This lives in idlin-server because it's the only crate that depends on
//! both idlin-sim (the constants' home) and the web tree's layout.

use idlin_sim::{FX_SCALE, RARITY_COLORS, RARITY_NAMES, TICK_HZ};

#[test]
fn export_constants_ts() {
    // Invariants the generated file leans on.
    assert_eq!(RARITY_NAMES.len(), 4, "rarity ladder is 4 wide");
    assert_eq!(RARITY_COLORS.len(), 4, "rarity ladder is 4 wide");

    let tick_ms = 1000 / TICK_HZ;
    let names = RARITY_NAMES
        .iter()
        .map(|n| format!("\"{n}\""))
        .collect::<Vec<_>>()
        .join(", ");
    let colors = RARITY_COLORS
        .iter()
        .map(|c| format!("\"{c}\""))
        .collect::<Vec<_>>()
        .join(", ");

    let body = format!(
        "// AUTO-GENERATED by idlin-server's export_constants test — do not edit.\n\
         export const TICK_HZ = {TICK_HZ};\n\
         export const TICK_MS = {tick_ms}; // 1000 / TICK_HZ\n\
         export const FX_SCALE = {FX_SCALE}; // Q16.16 fixed-point scale (1 << 16)\n\
         export const RARITY_NAMES = [{names}] as const;\n\
         export const RARITY_COLORS = [{colors}] as const;\n\
         // Numeric forms for the three.js scene (0xrrggbb).\n\
         export const RARITY_COLORS_NUM = RARITY_COLORS.map((c) => parseInt(c.slice(1), 16));\n"
    );

    std::fs::write("../../web/src/gen/constants.ts", body).expect("write constants.ts");
}
